import React, { useState, useEffect } from 'react';
import axios from 'axios';
import ResetPasswordModal from './ResetPasswordModal';

export default function StudentDashboard({ userName, handleLogout }) {
  const [allClasses, setAllClasses] = useState([]);
  const [selectedGrade, setSelectedGrade] = useState('Grade 10'); // Default grade
  const [showResetModal, setShowResetModal] = useState(false);

  useEffect(() => {
    axios.get('http://localhost:8081/api/timetable')
      .then(res => {
        if (res.data) setAllClasses(res.data);
      })
      .catch(err => console.error(err));
  }, []);

  const mySubjects = allClasses.filter(cls => cls.grade === selectedGrade);

  return (
    <div style={{ padding: '40px', backgroundColor: '#f8fafc', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
        <div>
            <h1 style={{ color: '#15803d', margin: 0 }}>Hello, {userName}! 🎓</h1>
            <p style={{ color: '#64748b', marginTop: '5px' }}>Check your upcoming classes and subjects.</p>
        </div>
        <div>
            <button onClick={() => setShowResetModal(true)} style={{ padding: '10px 15px', marginRight: '10px', background: '#3b82f6', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Change Password</button>
            <button onClick={handleLogout} style={{ padding: '10px 15px', background: '#ef4444', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>Logout</button>
        </div>
      </div>

      <div style={{ backgroundColor: 'white', borderRadius: '12px', padding: '20px', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #e2e8f0', paddingBottom: '10px' }}>
            <h3 style={{ color: '#334155', margin: 0 }}>My Subjects</h3>
            
            <select value={selectedGrade} onChange={(e) => setSelectedGrade(e.target.value)} style={{ padding: '8px', borderRadius: '6px', border: '1px solid #cbd5e1', outline: 'none' }}>
                <option value="Grade 10">Grade 10</option>
                <option value="Grade 11">Grade 11</option>
                <option value="A/L 2026">A/L 2026</option>
                <option value="A/L 2027">A/L 2027</option>
            </select>
        </div>
        
        {mySubjects.length > 0 ? (
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(250px, 1fr))', gap: '15px', marginTop: '20px' }}>
                {mySubjects.map((cls, index) => (
                    <div key={index} style={{ padding: '15px', backgroundColor: '#f1f8e9', borderLeft: '4px solid #15803d', borderRadius: '8px' }}>
                        <h4 style={{ margin: '0 0 5px 0', color: '#1e293b' }}>{cls.subject}</h4>
                        <p style={{ margin: '2px 0', fontSize: '13px', color: '#475569' }}>📅 {cls.day} | ⏰ {cls.time_slot}</p>
                        <p style={{ margin: '2px 0', fontSize: '13px', color: '#475569' }}>👨‍🏫 {cls.teacher}</p>
                    </div>
                ))}
            </div>
        ) : (
            <p style={{ color: '#ef4444', fontWeight: 'bold', marginTop: '20px' }}>No subjects found for this grade.</p>
        )}
      </div>

      {showResetModal && <ResetPasswordModal userName={userName} setShowResetModal={setShowResetModal} />}
    </div>
  );
}
